/**
 * CommonsBrandGlyph — the Commons mark (#1872 rebrand, replaces
 * RedditBrandGlyph). Original geometry: two overlapping circles sharing a
 * filled lens — a "commons" / shared-field motif, inheriting `currentColor`.
 * Decorative by default (`aria-hidden`): the consuming surface carries the
 * accessible name (e.g. a pill label). Brand marks are never mirrored in RTL,
 * mirroring KiteBrandGlyph's shape exactly.
 */

import { type ReactElement } from "react";

export function CommonsBrandGlyph({
  className,
}: {
  readonly className?: string;
}): ReactElement {
  return (
    <svg
      viewBox="0 0 32 32"
      fill="none"
      stroke="currentColor"
      aria-hidden="true"
      className={className}
    >
      <circle cx="12" cy="16" r="8.6" strokeWidth="2.4" />
      <circle cx="20" cy="16" r="8.6" strokeWidth="2.4" />
      <path
        d="M16 8.55 A8.6 8.6 0 0 1 16 23.45 A8.6 8.6 0 0 1 16 8.55 Z"
        fill="currentColor"
        opacity="0.9"
      />
    </svg>
  );
}


