--- frontends/range-mfe/src/components/content/KiteBrandGlyph.tsx (60 lines) ---
/**
 * KiteBrandGlyph — the Kite mark (#1874). Original geometry: a monoline kite
 * quadrilateral with crossed spars, inheriting `currentColor`, no separate
 * dark asset. Decorative by default (`aria-hidden`): the consuming surface
 * carries the accessible name (e.g. the page <h1> or the nav item label).
 * Brand marks are never mirrored in RTL and are stroked, not filled.
 *
 * The crossbar (the second <path>) reads as intended at 32px but dissolves
 * into anti-aliasing noise below ~20px — worse than omitting it. `renderedPx`
 * drives that threshold and NOTHING else: this svg carries no width/height, so
 * `className` alone does the actual sizing. The prop is the call site telling
 * the glyph how large its CSS will end up rendering it, which is why every call
 * site passes a number matching its own `className` — they can disagree, and
 * only the crossbar notices.
 *
 * Optional `label` (#1875): when the glyph is genuinely unwrapped — not
 * itself the sole content of an interactive control that already carries an
 * accessible name — pass `label` and it renders `role="img"` +
 * `aria-label={label}` instead of `aria-hidden`. This is what lets KiteApp's
 * standalone nav-rail logo share this component rather than maintaining its
 * own duplicate inline `<svg>`.
 */

import { type ReactElement } from "react";

const CROSSBAR_MIN_SIZE = 20;

export function KiteBrandGlyph({
  className,
  renderedPx = 32,
  label,
}: {
  readonly className?: string;
  readonly renderedPx?: number;
  readonly label?: string;
}): ReactElement {
  const a11yProps =
    label !== undefined
      ? ({ role: "img", "aria-label": label } as const)
      : ({ "aria-hidden": "true" } as const);
  return (
    <svg
      viewBox="0 0 32 32"
      fill="none"
      stroke="currentColor"
      className={className}
      {...a11yProps}
    >
      <path
        d="M16 2.5 L27 13 L16 29.5 L5 13 Z"
        strokeWidth="2.4"
        strokeLinejoin="round"
      />
      {renderedPx >= CROSSBAR_MIN_SIZE && (
        <path d="M5 13 H27 M16 2.5 V29.5" strokeWidth="1.6" opacity="0.5" />
      )}
    </svg>
  );
}


