/**
 * KiteContentErrorRetry — shared hard-error state for the X content admin
 * tabs: a message line plus a Retry button. Was duplicated byte-for-byte
 * between TrendsTab and TimelineTab; the two tabs share ownership so a
 * future a11y/visual tweak to the pattern doesn't have to land twice.
 */
import { type ReactElement } from "react";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";

interface KiteContentErrorRetryProps {
  readonly message: string;
  readonly onRetry: () => void;
}

export function KiteContentErrorRetry({
  message,
  onRetry,
}: KiteContentErrorRetryProps): ReactElement {
  return (
    <div className="flex flex-col items-center gap-cog-3 py-cog-6">
      <p role="alert" className="text-body-sm text-cog-text-secondary">
        {message}
      </p>
      <button
        type="button"
        onClick={onRetry}
        className="inline-flex min-h-btn items-center justify-center rounded-md border border-cog-border bg-cog-surface px-cog-4 text-body-sm font-medium text-cog-text-primary hover:bg-cog-surface-muted focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus"
      >
        {m.range_kitecontent_error_retry_cta()}
      </button>
    </div>
  );
}


