/**
 * TimelinePostRow — one post in the X content admin Timeline (quick-review
 * admin LIST, not the immersive clone).
 *
 * Row anatomy: author monogram avatar (tinted by `author_avatar_color` when
 * present) · display name + @username + relative time · body (line-clamped to
 * 2) · reply/repost/like counts with inline glyphs + sr-only labels · badges
 * (Synthetic for AI posts, Event when scenario_event_id) · a delete action.
 *
 * cog-* tokens throughout — this is an ADMIN surface, not the x-* faithful
 * palette. The avatar + count glyphs are decorative (aria-hidden); meaning is
 * carried by text.
 */

import { type ReactElement } from "react";
import {
  Heart,
  MessageCircle,
  Repeat2,
  Trash2,
} from "@omnicore-platform/ui/icons";
import { useLocale } from "@omnicore-platform/platform-chrome";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { type Post } from "../../api/feed";

/** Localized compact relative time ("5 minutes ago", "yesterday", …). */
export function relativeTime(
  iso: string,
  locale: string,
  now: number = Date.now(),
): string {
  const then = Date.parse(iso);
  if (Number.isNaN(then)) return "";
  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });
  let duration = (then - now) / 1000;
  const divisions: readonly {
    amount: number;
    unit: Intl.RelativeTimeFormatUnit;
  }[] = [
    { amount: 60, unit: "second" },
    { amount: 60, unit: "minute" },
    { amount: 24, unit: "hour" },
    { amount: 7, unit: "day" },
    { amount: Number.POSITIVE_INFINITY, unit: "week" },
  ];
  for (const division of divisions) {
    if (Math.abs(duration) < division.amount) {
      return rtf.format(Math.round(duration), division.unit);
    }
    duration /= division.amount;
  }
  return "";
}

/** Decorative inline count glyphs — shared fleet lucide source. */
const ReplyGlyph = (
  <MessageCircle aria-hidden="true" className="h-cog-3-5 w-cog-3-5" />
);
const RepostGlyph = <Repeat2 aria-hidden="true" className="h-cog-3-5 w-cog-3-5" />;
const LikeGlyph = <Heart aria-hidden="true" className="h-cog-3-5 w-cog-3-5" />;

function Count({
  glyph,
  count,
  label,
}: {
  readonly glyph: ReactElement;
  readonly count: number;
  readonly label: string;
}): ReactElement {
  return (
    <span className="inline-flex items-center gap-cog-1 text-caption tabular-nums text-cog-text-tertiary">
      {glyph}
      <span aria-hidden="true">{count}</span>
      <span className="sr-only">{label}</span>
    </span>
  );
}

export interface TimelinePostRowProps {
  readonly post: Post;
  readonly onDelete: (post: Post) => void;
}

export function TimelinePostRow({
  post,
  onDelete,
}: TimelinePostRowProps): ReactElement {
  const { locale } = useLocale();
  const displayName = post.author_display_name?.trim()
    ? post.author_display_name
    : post.author_username;
  const monogram = displayName.charAt(0).toUpperCase();
  const avatarColor = post.author_avatar_color?.trim()
    ? post.author_avatar_color
    : undefined;

  return (
    <li className="flex items-start gap-cog-3 border-b border-cog-divider px-cog-3 py-cog-3 last:border-b-0">
      {/* Monogram avatar — decorative; the name text carries meaning. */}
      <span
        aria-hidden="true"
        className="flex size-cog-6-5 shrink-0 items-center justify-center rounded-pill bg-cog-surface-muted text-body-sm font-semibold text-white"
        style={avatarColor !== undefined ? { backgroundColor: avatarColor } : undefined}
      >
        {monogram}
      </span>

      <div className="flex min-w-cog-0 flex-1 flex-col gap-cog-1">
        {/* Repost attribution eyebrow — ADDITIVE, shown only for repost entries. */}
        {post.reposted_by_username?.trim() ? (
          <div className="flex items-center gap-cog-1 text-caption text-cog-text-tertiary">
            {RepostGlyph}
            <span>
              {m.range_kitecontent_reposted_by({
                name: post.reposted_by_display_name?.trim()
                  ? post.reposted_by_display_name
                  : post.reposted_by_username,
              })}
            </span>
          </div>
        ) : null}
        <div className="flex flex-wrap items-center gap-cog-2">
          <span className="text-body-sm font-semibold text-cog-text-primary">
            {displayName}
          </span>
          <span className="text-caption text-cog-text-tertiary">
            {m.range_post_handle({ handle: post.author_username })}
          </span>
          <span aria-hidden="true" className="text-caption text-cog-text-tertiary">
            ·
          </span>
          <time
            dateTime={post.created_at}
            className="text-caption text-cog-text-tertiary"
          >
            {relativeTime(post.created_at, locale)}
          </time>

          {post.is_ai_generated && (
            <span className="inline-flex items-center rounded-pill bg-cog-violet-50 px-cog-2 py-cog-0-5 text-micro font-medium text-cog-violet-600">
              {m.range_post_synthetic_badge()}
            </span>
          )}
          {Boolean(post.scenario_event_id) && (
            <span className="inline-flex items-center rounded-pill border border-cog-border bg-cog-surface-muted px-cog-2 py-cog-0-5 text-micro font-medium text-cog-text-secondary">
              {m.range_kitecontent_badge_event()}
            </span>
          )}
        </div>

        <p className="line-clamp-2 text-body-sm text-cog-text-primary">
          {post.body}
        </p>

        <div className="flex items-center gap-cog-4">
          <Count
            glyph={ReplyGlyph}
            count={post.reply_count}
            label={m.range_kitecontent_replies_label({ count: post.reply_count })}
          />
          <Count
            glyph={RepostGlyph}
            count={post.repost_count}
            label={m.range_kitecontent_reposts_label({ count: post.repost_count })}
          />
          <Count
            glyph={LikeGlyph}
            count={post.like_count}
            label={m.range_kitecontent_likes_label({ count: post.like_count })}
          />
        </div>
      </div>

      <button
        type="button"
        aria-label={m.range_kitecontent_delete_post_label({ author: displayName })}
        onClick={() => onDelete(post)}
        className="flex min-h-tap min-w-tap shrink-0 items-center justify-center rounded-md text-cog-text-tertiary hover:bg-cog-surface-muted hover:text-cog-danger-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus"
      >
        <Trash2 aria-hidden="true" className="h-cog-4 w-cog-4" />
      </button>
    </li>
  );
}


--- frontends/range-mfe/src/components/content/TimelineTab.tsx (219 lines) ---
/**
 * TimelineTab — the Timeline tab of the X content admin page: an admin
 * TABLE/LIST of the exercise's posts for quick review (NOT the immersive
 * clone). Reuses the cursor-paginated feed data layer (useFeed → listFeed,
 * which unwraps the { data: ... } envelope and defaults omitted arrays).
 *
 * Toolbar: a client-side search (body + author display name / username) and a
 * typology select — Human (`!is_ai_generated`), Synthetic (`is_ai_generated`
 * without a scenario_event_id), Event reaction (`!!scenario_event_id`).
 *
 * Delete: per-row action → shared destructive {@link ConfirmDialog} → the
 * existing DELETE /api/v1/range/posts/{post_id} route; on success the row is
 * dropped from the local list (a deleted-ids overlay — useFeed's cache is
 * untouched). Failures surface error.message from the {error:{code,message}}
 * envelope in a role="alert" above the list.
 *
 * A "What's happening" trends side card ({@link WhatsHappeningCard}) sits to
 * the RIGHT of the post list at lg+ widths (stacked below on smaller),
 * mirroring what participants see — it mounts only when trends data exists.
 */

import { useState, type ReactElement } from "react";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { deletePost, feedEntryKey, type Post } from "../../api/feed";
import { useFeed } from "../../hooks/useFeed";
import { useConfirmedAction } from "../../hooks/useConfirmedAction";
import { ConfirmDialog } from "../ConfirmDialog";
import { KiteContentErrorRetry } from "./KiteContentErrorRetry";
import { TimelinePostRow } from "./TimelinePostRow";
import { WhatsHappeningCard } from "./WhatsHappeningCard";

export type TimelineTypology = "all" | "human" | "synthetic" | "event";

const TYPOLOGIES: readonly TimelineTypology[] = [
  "all",
  "human",
  "synthetic",
  "event",
];

function typologyLabel(typology: TimelineTypology): string {
  switch (typology) {
    case "all":
      return m.range_kitecontent_typology_all();
    case "human":
      return m.range_kitecontent_typology_human();
    case "synthetic":
      return m.range_kitecontent_typology_synthetic();
    case "event":
      return m.range_kitecontent_typology_event();
  }
}

function matchesTypology(post: Post, typology: TimelineTypology): boolean {
  switch (typology) {
    case "all":
      return true;
    case "human":
      return !post.is_ai_generated;
    case "synthetic":
      return post.is_ai_generated && !post.scenario_event_id;
    case "event":
      return Boolean(post.scenario_event_id);
  }
}

function matchesQuery(post: Post, query: string): boolean {
  if (query === "") return true;
  const haystack = [
    post.body,
    post.author_display_name ?? "",
    post.author_username,
  ]
    .join("\n")
    .toLowerCase();
  return haystack.includes(query);
}

export interface TimelineTabProps {
  readonly exerciseId: string;
}

export function TimelineTab({ exerciseId }: TimelineTabProps): ReactElement {
  const feed = useFeed(exerciseId);
  const [query, setQuery] = useState("");
  const [typology, setTypology] = useState<TimelineTypology>("all");
  const [deletedIds, setDeletedIds] = useState<ReadonlySet<string>>(new Set());
  const [pendingDelete, setPendingDelete] = useState<Post | null>(null);

  const deleteAction = useConfirmedAction({
    action: async () => {
      if (pendingDelete === null) return;
      // AC4: pass reposted_by_character_id when the row is a repost entry so
      // the BFF removes only the repost interaction, not the original post.
      // When absent (undefined or ""), deletePost omits the query param and
      // falls back to the soft-delete path.
      await deletePost(pendingDelete.id, pendingDelete.reposted_by_character_id);
    },
    successMessage: m.range_kitecontent_delete_success(),
    onDone: () => {
      if (pendingDelete === null) return;
      setDeletedIds((prev) => {
        const next = new Set(prev);
        // Track by feedEntryKey so a repost deletion does not hide the
        // original post row (both share the same post.id).
        next.add(feedEntryKey(pendingDelete));
        return next;
      });
      setPendingDelete(null);
    },
  });

  if (feed.state === "loading") {
    return (
      <p
        role="status"
        className="py-cog-6 text-center text-body-sm text-cog-text-tertiary"
      >
        {m.range_kitecontent_loading()}
      </p>
    );
  }

  if (feed.state === "error") {
    return (
      <KiteContentErrorRetry message={feed.message} onRetry={feed.refetch} />
    );
  }

  // The deleted-ids overlay + tombstones never render in the admin list.
  // Use feedEntryKey (not post.id) so deleting a REPOST entry does not hide
  // the ORIGINAL — repost entries share the original's post.id but carry a
  // distinct feedEntryKey (id:rt:reposted_by_character_id).
  const basePosts = feed.posts.filter(
    (post) => !deletedIds.has(feedEntryKey(post)) && !post.is_deleted,
  );
  const normalizedQuery = query.trim().toLowerCase();
  const visiblePosts = basePosts.filter(
    (post) =>
      matchesTypology(post, typology) && matchesQuery(post, normalizedQuery),
  );

  return (
    <div className="flex flex-col gap-cog-4 lg:flex-row lg:items-start">
      <div className="flex min-w-cog-0 max-w-cog-feed flex-1 flex-col gap-cog-4">
        {/* Toolbar: client-side search + typology filter. */}
        <div className="flex flex-wrap items-center gap-cog-3">
          <input
            type="search"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            aria-label={m.range_kitecontent_search_label()}
            placeholder={m.range_kitecontent_search_label()}
            className="min-h-btn flex-1 rounded-md border border-cog-border bg-cog-surface px-cog-3 text-body-sm text-cog-text-primary placeholder:text-cog-text-tertiary focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus"
          />
          <select
            value={typology}
            onChange={(e) => setTypology(e.target.value as TimelineTypology)}
            aria-label={m.range_kitecontent_typology_label()}
            className="min-h-btn rounded-md border border-cog-border bg-cog-surface px-cog-3 text-body-sm text-cog-text-primary focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus"
          >
            {TYPOLOGIES.map((value) => (
              <option key={value} value={value}>
                {typologyLabel(value)}
              </option>
            ))}
          </select>
        </div>

        {basePosts.length === 0 ? (
          <p className="py-cog-6 text-center text-body-sm text-cog-text-tertiary">
            {m.range_kitecontent_empty()}
          </p>
        ) : visiblePosts.length === 0 ? (
          <p className="py-cog-6 text-center text-body-sm text-cog-text-tertiary">
            {m.range_kitecontent_empty_filtered()}
          </p>
        ) : (
          <ul className="flex flex-col rounded-lg border border-cog-border bg-cog-surface">
            {visiblePosts.map((post) => (
              <TimelinePostRow
                key={feedEntryKey(post)}
                post={post}
                onDelete={setPendingDelete}
              />
            ))}
          </ul>
        )}

        {feed.hasMore && (
          <button
            type="button"
            onClick={feed.loadMore}
            className="inline-flex min-h-btn items-center justify-center self-center rounded-md border border-cog-border bg-cog-surface px-cog-4 text-body-sm font-medium text-cog-text-primary hover:bg-cog-surface-muted focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus"
          >
            {m.range_feed_load_more()}
          </button>
        )}
      </div>

      {/* The participant-mirroring trends side card — quiet unless data exists. */}
      <WhatsHappeningCard exerciseId={exerciseId} />

      {pendingDelete !== null && (
        <ConfirmDialog
          title={m.range_kitecontent_delete_confirm_title()}
          body={m.range_kitecontent_delete_confirm_body()}
          confirmLabel={m.range_kitecontent_delete_confirm_cta()}
          cancelLabel={m.range_kitecontent_delete_confirm_cancel()}
          isBusy={deleteAction.isBusy}
          error={deleteAction.error}
          onConfirm={() => void deleteAction.run()}
          onCancel={() => setPendingDelete(null)}
        />
      )}
    </div>
  );
}


--- frontends/range-mfe/src/components/content/TrendTopicForm.tsx (166 lines) ---
/**
 * TrendTopicForm — the shared inline create/edit form for a custom trending
 * topic (X content admin Trends tab). Label is required (save disabled while
 * blank); description is optional. The parent passes the async `onSave`; the
 * form owns the busy flag and surfaces the server error.message via a toast,
 * staying open for correction: a 409 duplicate-label conflict (RangeApiError
