            id={labelId}
            type="text"
            value={body}
            required
            aria-required="true"
            aria-invalid={isInvalid}
            aria-describedby={isInvalid ? `${hintId} ${errorId}` : hintId}
            onChange={(e) => setBody(toBody(e.target.value))}
            className="min-w-cog-0 flex-1 bg-transparent pe-cog-3 text-body-sm text-cog-text-primary focus-visible:outline-none"
          />
        </div>
        <p id={hintId} className="text-caption text-cog-text-tertiary">
          {m.range_kitecontent_trends_label_hint()}
        </p>
        {isInvalid && (
          <p
            id={errorId}
            role="alert"
            className="text-caption text-cog-danger-500 dark:text-cog-danger-dark"
          >
            {m.range_kitecontent_trends_label_invalid()}
          </p>
        )}
      </div>

      <div className="flex flex-col gap-cog-1">
        <label
          htmlFor={descriptionId}
          className="text-caption font-medium text-cog-text-secondary"
        >
          {m.range_kitecontent_trends_description_label()}
        </label>
        <input
          id={descriptionId}
          type="text"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          className="min-h-btn rounded-md border border-cog-border bg-cog-surface px-cog-3 text-body-sm text-cog-text-primary focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus"
        />
      </div>

      <div className="flex items-center justify-end gap-cog-2">
        <button
          type="button"
          onClick={onCancel}
          className="inline-flex min-h-btn items-center justify-center rounded-md border border-cog-border bg-cog-surface px-cog-4 text-body-sm font-medium text-cog-text-primary hover:bg-cog-surface-muted focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus"
