          type="submit"
          disabled={!canSave}
          aria-busy={isSaving}
          className="inline-flex min-h-btn items-center justify-center rounded-md bg-cog-blue-600 px-cog-4 text-body-sm font-semibold text-white hover:bg-cog-blue-700 disabled:bg-cog-surface-muted disabled:text-cog-text-tertiary focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus"
        >
          {m.range_kitecontent_trends_save()}
        </button>
      </div>
    </form>
  );
}


