      .finally(() => {
        setIsUnpinning(false);
      });
  };

  return (
    <section
      aria-label={m.range_kitecontent_trends_list_title()}
      className="flex flex-col gap-cog-2 rounded-lg border border-cog-border bg-cog-surface p-cog-4"
    >
      <header className="flex items-start justify-between gap-cog-3">
        <div className="flex min-w-cog-0 flex-col gap-cog-1">
          <h2 className="text-heading-md text-cog-text-primary">
            {m.range_kitecontent_trends_list_title()}
          </h2>
          <p className="text-body-sm text-cog-text-secondary">
            {m.range_kitecontent_trends_list_description()}
          </p>
        </div>
        <button
          type="button"
          onClick={onChanged}
          disabled={refreshing}
          aria-busy={refreshing}
          className="inline-flex min-h-btn-sm shrink-0 items-center justify-center gap-cog-1 rounded-md bg-transparent px-cog-3 text-body-sm font-medium text-cog-text-secondary hover:bg-cog-surface-muted disabled:opacity-60 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus"
        >
          <RefreshCw
            aria-hidden="true"
            className={
              refreshing
                ? "h-cog-3-5 w-cog-3-5 motion-safe:animate-spin"
                : "h-cog-3-5 w-cog-3-5"
            }
          />
