/**
 * mergeTrends — the single authority for the order participants see in the
 * Kite Trending-now card, shared by the admin Trends tab and the participant
 * {@link WhatsHappeningCard} so the two cannot drift (#2088 follow-up).
 *
 * `TrendTopic.position` is a 0-based slot index into the MERGED list, not an
 * index within the custom set: an instructor can therefore place a curated
 * topic anywhere among the volume-ranked auto trends, which the earlier
 * custom-block-then-auto-block split made impossible. Auto trends keep their
 * incoming (score) order among themselves and fill the slots the custom
 * anchors leave — they are derived from hashtag volume, so their relative rank
 * is not the instructor's to set. To rank one, pin it (which mints a custom
 * topic that owns a slot).
 *
 * An auto trend whose label case-insensitively matches a custom label is that
 * same topic already pinned — it collapses into the custom entry rather than
 * rendering twice, and its volume rides along as `postCount`.
 */

import { type AutoTrend, type TrendTopic } from "../../api/trends";

/** One row of the merged trend list, tagged by where it came from. */
export type MergedTrendEntry =
  | {
      readonly kind: "custom";
      readonly topic: TrendTopic;
      /** Volume of the collapsed auto twin, or null when it isn't trending. */
      readonly postCount: number | null;
    }
  | { readonly kind: "auto"; readonly trend: AutoTrend };

/**
 * Order custom topics by slot, then by created_at, then by id — a total order,
 * so two topics sharing a position (sparse or hand-edited data) never render
 * in a load-dependent order.
 */
function bySlotThenAge(a: TrendTopic, b: TrendTopic): number {
  if (a.position !== b.position) return a.position - b.position;
  if (a.created_at !== b.created_at)
    return a.created_at < b.created_at ? -1 : 1;
  return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
}

export function mergeTrends(
  custom: readonly TrendTopic[],
  auto: readonly AutoTrend[],
): readonly MergedTrendEntry[] {
  const pinnedCounts = new Map<string, number>();
  for (const topic of custom) pinnedCounts.set(topic.label.toLowerCase(), 0);

  // Collapse the pinned twins: record their volume on the custom entry and
  // drop them from the auto fill, so a pinned label consumes exactly one slot.
  const fill: AutoTrend[] = [];
  for (const trend of auto) {
    const key = trend.label.toLowerCase();
    if (pinnedCounts.has(key)) {
      pinnedCounts.set(key, trend.post_count);
    } else {
      fill.push(trend);
    }
  }

  const anchors = [...custom].sort(bySlotThenAge);
  const merged: MergedTrendEntry[] = fill.map((trend) => ({
    kind: "auto",
    trend,
  }));

  // Insert each anchor at its slot against the list built so far, so earlier
  // anchors shift the later ones down exactly as the admin preview shows.
  // A slot past the end appends; a negative slot clamps to the top. `cursor`
  // keeps two anchors sharing a slot in their tie-broken order instead of
  // letting the second insert push the first back down.
  let cursor = -1;
  for (const topic of anchors) {
    const count = pinnedCounts.get(topic.label.toLowerCase()) ?? 0;
    const slot = Math.min(
      Math.max(topic.position, cursor + 1),
      merged.length,
    );
    cursor = slot;
    merged.splice(slot, 0, {
      kind: "custom",
      topic,
      postCount: count > 0 ? count : null,
    });
  }

  return merged;
}



