/** Localized compact relative time ("5 minutes ago", "yesterday", …). */
export function relativeTime(
  iso: string,
  locale: string,
  now: number = Date.now(),
): string {
  const then = Date.parse(iso);
  if (Number.isNaN(then)) return "";
  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });
  let duration = (then - now) / 1000;
  const divisions: readonly {
    amount: number;
    unit: Intl.RelativeTimeFormatUnit;
  }[] = [
    { amount: 60, unit: "second" },
    { amount: 60, unit: "minute" },
    { amount: 24, unit: "hour" },
    { amount: 7, unit: "day" },
    { amount: Number.POSITIVE_INFINITY, unit: "week" },
  ];
  for (const division of divisions) {
    if (Math.abs(duration) < division.amount) {
      return rtf.format(Math.round(duration), division.unit);
    }
    duration /= division.amount;
  }
  return "";
}

/** Decorative inline count glyphs — shared fleet lucide source. */
const ReplyGlyph = (
  <MessageCircle aria-hidden="true" className="h-cog-3-5 w-cog-3-5" />
