            <span>
              {m.range_kitecontent_reposted_by({
                name: post.reposted_by_display_name?.trim()
                  ? post.reposted_by_display_name
                  : post.reposted_by_username,
              })}
            </span>
          </div>
        ) : null}
        <div className="flex flex-wrap items-center gap-cog-2">
          <span className="text-body-sm font-semibold text-cog-text-primary">
            {displayName}
          </span>
          <span className="text-caption text-cog-text-tertiary">
            {m.range_post_handle({ handle: post.author_username })}
          </span>
          <span aria-hidden="true" className="text-caption text-cog-text-tertiary">
            ·
