/**
 * TrendTopicForm — the shared inline create/edit form for a custom trending
 * topic (X content admin Trends tab). Label is required (save disabled while
 * blank); description is optional. The parent passes the async `onSave`; the
 * form owns the busy flag and surfaces the server error.message via a toast,
 * staying open for correction: a 409 duplicate-label conflict (RangeApiError
 * with status 409, user-correctable) surfaces as a warning toast, everything
 * else as a danger toast. cog-* tokens — ADMIN surface.
 *
 * Hashtag shape (#2088 follow-up): a custom topic sits in the same participant
 * list as the auto-calculated hashtag trends, so a bare word reads as broken
 * next to them. The "#" is therefore a fixed adornment rather than something
 * the instructor has to remember — the input holds only the BODY, a leading
 * "#" typed or pasted is absorbed instead of doubled, and a body outside
 * [A-Za-z0-9_]{1,64} surfaces an inline error and blocks Save rather than
 * being silently slugified into something the instructor did not write. The
 * service is the real gate; this mirrors it so the error arrives before the
 * round-trip. Editing a legacy bare label (authored before this rule) shows
 * the body as-is and re-saves it hashtag-shaped.
 */

import { useId, useState, type ReactElement } from "react";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { useToast } from "@omnicore-platform/platform-chrome/toast";
import { RangeApiError } from "../../api/exercises";
import { toErrorMessage } from "../../hooks/toErrorMessage";

/** Mirrors range-svc's `_LABEL_BODY_RE` — the service owns the real gate. */
const LABEL_BODY_RE = /^[A-Za-z0-9_]{1,64}$/;

/** Strip the leading whitespace and "#"s the adornment already stands for. */
function toBody(raw: string): string {
  return raw.replace(/^[\s#]+/, "");
}

export interface TrendTopicFormProps {
  readonly initialLabel?: string;
  readonly initialDescription?: string;
  /** Resolves on success (parent closes + refetches); rejects to stay open. */
  readonly onSave: (label: string, description: string) => Promise<void>;
  readonly onCancel: () => void;
}

export function TrendTopicForm({
  initialLabel = "",
  initialDescription = "",
  onSave,
  onCancel,
}: TrendTopicFormProps): ReactElement {
  const labelId = useId();
  const hintId = useId();
  const errorId = useId();
  const descriptionId = useId();
  const toast = useToast();
  const [body, setBody] = useState(() => toBody(initialLabel));
  const [description, setDescription] = useState(initialDescription);
  const [isSaving, setIsSaving] = useState(false);

  const trimmedBody = body.trim();
  // A blank field is "not started yet", not an error — Save is disabled either
  // way, but only a non-empty invalid body earns the inline message.
  const isInvalid = trimmedBody !== "" && !LABEL_BODY_RE.test(trimmedBody);
  const canSave = LABEL_BODY_RE.test(trimmedBody) && !isSaving;

  const submit = (): void => {
    if (!canSave) return;
    setIsSaving(true);
    onSave(`#${trimmedBody}`, description.trim())
      .catch((err: unknown) => {
        const message = toErrorMessage(err, m.range_network_unknown_error());
        if (err instanceof RangeApiError && err.status === 409) {
          toast.warning(message);
        } else {
          toast.danger(message);
        }
      })
      .finally(() => {
        setIsSaving(false);
      });
  };

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        submit();
      }}
      className="flex flex-col gap-cog-3 rounded-md border border-cog-border bg-cog-surface-muted p-cog-3"
    >
      <div className="flex flex-col gap-cog-1">
        <label
          htmlFor={labelId}
          className="text-caption font-medium text-cog-text-secondary"
        >
          {m.range_kitecontent_trends_label_label()}
        </label>
        <div className="flex min-h-btn items-center gap-cog-1 rounded-md border border-cog-border bg-cog-surface ps-cog-3 focus-within:outline focus-within:outline-2 focus-within:outline-offset-2 focus-within:outline-cog-focus">
          <span
            aria-hidden="true"
            className="shrink-0 text-body-sm font-semibold text-cog-text-tertiary"
          >
            #
          </span>
          <input
            id={labelId}
            type="text"
            value={body}
            required
            aria-required="true"
            aria-invalid={isInvalid}
            aria-describedby={isInvalid ? `${hintId} ${errorId}` : hintId}
            onChange={(e) => setBody(toBody(e.target.value))}
            className="min-w-cog-0 flex-1 bg-transparent pe-cog-3 text-body-sm text-cog-text-primary focus-visible:outline-none"
          />
        </div>
        <p id={hintId} className="text-caption text-cog-text-tertiary">
          {m.range_kitecontent_trends_label_hint()}
        </p>
        {isInvalid && (
          <p
            id={errorId}
            role="alert"
            className="text-caption text-cog-danger-500 dark:text-cog-danger-dark"
          >
            {m.range_kitecontent_trends_label_invalid()}
          </p>
        )}
      </div>

      <div className="flex flex-col gap-cog-1">
        <label
          htmlFor={descriptionId}
          className="text-caption font-medium text-cog-text-secondary"
        >
          {m.range_kitecontent_trends_description_label()}
        </label>
        <input
          id={descriptionId}
          type="text"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          className="min-h-btn rounded-md border border-cog-border bg-cog-surface px-cog-3 text-body-sm text-cog-text-primary focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus"
        />
      </div>

      <div className="flex items-center justify-end gap-cog-2">
        <button
          type="button"
          onClick={onCancel}
          className="inline-flex min-h-btn items-center justify-center rounded-md border border-cog-border bg-cog-surface px-cog-4 text-body-sm font-medium text-cog-text-primary hover:bg-cog-surface-muted focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus"
        >
          {m.range_kitecontent_trends_cancel()}
        </button>
        <button
          type="submit"
          disabled={!canSave}
          aria-busy={isSaving}
          className="inline-flex min-h-btn items-center justify-center rounded-md bg-cog-blue-600 px-cog-4 text-body-sm font-semibold text-white hover:bg-cog-blue-700 disabled:bg-cog-surface-muted disabled:text-cog-text-tertiary focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus"
        >
          {m.range_kitecontent_trends_save()}
        </button>
      </div>
    </form>
  );
}


