/**
 * TrendsListCard — the single combined trending-topics card for the Kite
 * content admin Trends tab (#2088 follow-up to the #262 trends slice).
 *
 * This REPLACES the earlier three-card layout (CustomTrendsCard,
 * AutoTrendsCard, and TrendsTab's read-only "participant order" preview) with
 * one ranked list: what an instructor sees here is exactly the order
 * participants get, because it renders the same {@link mergeTrends} helper
 * the participant rail consumes — there is no longer a separate preview to
 * keep in sync with two editing surfaces.
 *
 * A row's SOURCE still matters for what it can do (only a custom row owns a
 * slot to PATCH/DELETE; an auto row's rank is derived from hashtag volume),
 * but it is no longer what SECTION the row lives in — a custom topic can sit
 * between two auto trends, and a blue marker on its left edge is the only
 * thing distinguishing "an instructor placed this" from "volume put this
 * here." A custom row's marker is `bg-cog-blue-600` (the primary Indigo
 * accent) rather than the vertical's own violet accent, matching the literal
 * "a blue marker means you placed it" copy in
 * `range_kitecontent_trends_list_footer`.
 *
 * Reordering delegates entirely to {@link useTrendReorder}: this component
 * only decides WHICH two slots moved (drag source/target, or one arrow-key
 * step) and hands them to `move(fromSlot, toSlot)` — the hook already knows
 * that moving an `auto` row mints a `create` (pins it) while a `custom` row
 * gets a `patch`, and that neighbours may shift too. Two ways to trigger the
 * same move are offered on purpose: native HTML5 drag-and-drop (no new
 * dependency) for pointer users, and a same-row ArrowUp/ArrowDown handler PLUS
 * a pair of `sr-only focus:not-sr-only` "Move up"/"Move down" buttons for
 * keyboard users who may not discover that the grip itself is focusable. Both
 * paths converge on the same `move()` call, so there is exactly one place a
 * reorder bug could hide.
 *
 * Edit/delete on a custom row branch on `postCount`, mirroring the contract
 * `CustomTrendsCard` established: `postCount !== null` means this label is
 * ALSO a currently-trending auto trend that got pinned, so the destructive
 * action is really "let volume rank it again" — no confirm dialog, since
 * un-pinning loses no authored content. `postCount === null` means the
 * instructor authored this topic from nothing, so it keeps the destructive
 * {@link ConfirmDialog} flow.
 */

import {
  useId,
  useRef,
  useState,
  type DragEvent,
  type KeyboardEvent,
  type ReactElement,
} from "react";
import {
  Edit2,
  GripVertical,
  Plus,
  RefreshCw,
  Trash2,
} from "@omnicore-platform/ui/icons";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { useToast } from "@omnicore-platform/platform-chrome/toast";
import {
  createTrendTopic,
  deleteTrendTopic,
  updateTrendTopic,
  type AutoTrend,
  type TrendTopic,
} from "../../api/trends";
import { mergeTrends, type MergedTrendEntry } from "./mergeTrends";
import { useTrendReorder } from "../../hooks/useTrendReorder";
import { useConfirmedAction } from "../../hooks/useConfirmedAction";
import { toErrorMessage } from "../../hooks/toErrorMessage";
import { ConfirmDialog } from "../ConfirmDialog";
import { TrendTopicForm } from "./TrendTopicForm";

/** Mirrors the participant rail's cap (KiteApp's What's-happening card). */
const PARTICIPANT_TOP_ENTRIES = 5;

const ICON_BUTTON_CLASS =
  "flex size-cog-6 shrink-0 items-center justify-center rounded-md text-cog-text-tertiary hover:bg-cog-surface-muted hover:text-cog-text-primary disabled:bg-cog-surface-muted disabled:text-cog-text-tertiary focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus";

/** Decorative reorder-handle glyph. */
function GripGlyph(): ReactElement {
  return <GripVertical aria-hidden="true" className="h-cog-4 w-cog-4" />;
}

/** Decorative pencil/edit glyph. */
function PencilGlyph(): ReactElement {
  return <Edit2 aria-hidden="true" className="h-cog-4 w-cog-4" />;
}

/** Decorative trash glyph. */
function TrashGlyph(): ReactElement {
  return <Trash2 aria-hidden="true" className="h-cog-4 w-cog-4" />;
}

export interface TrendsListCardProps {
  readonly exerciseId: string;
  readonly topics: readonly TrendTopic[];
  readonly autoTrends: readonly AutoTrend[];
  /** True while a trends refetch is in flight (Recalculate busy state). */
  readonly refreshing: boolean;
  /** Refetch the trends after any successful mutation, and for Recalculate. */
  readonly onChanged: () => void;
}

/** A one-shot label for the entry at a slot, used by aria-labels and toasts. */
function entryLabel(entry: MergedTrendEntry): string {
  return entry.kind === "custom" ? entry.topic.label : entry.trend.label;
}

export function TrendsListCard({
  exerciseId,
  topics,
  autoTrends,
  refreshing,
  onChanged,
}: TrendsListCardProps): ReactElement {
  const toast = useToast();
  const reorderHintId = useId();
  const [isAdding, setIsAdding] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [pendingDelete, setPendingDelete] = useState<TrendTopic | null>(null);
  const [isUnpinning, setIsUnpinning] = useState(false);
  const [announcement, setAnnouncement] = useState("");
  // Drag state lives in a ref, not React state: dragover fires continuously
  // while dragging, and re-rendering on every one of those would thrash the
  // list — only the drop TARGET needs to be visible, so that alone is state.
  const dragSlotRef = useRef<number | null>(null);
  const [dropTargetSlot, setDropTargetSlot] = useState<number | null>(null);

  const merged = mergeTrends(topics, autoTrends);

  const move = useTrendReorder({
    exerciseId,
    merged,
    onChanged: () => {
      onChanged();
    },
  });

  const runMove = (fromSlot: number, toSlot: number): void => {
    if (fromSlot === toSlot) return;
    const entry = merged[fromSlot];
    if (entry === undefined) return;
    move.move(fromSlot, toSlot);
    setAnnouncement(
      m.range_kitecontent_trends_moved_announcement({
        label: entryLabel(entry),
        position: toSlot + 1,
      }),
    );
  };

  const handleDragStart = (slot: number) => (e: DragEvent<HTMLLIElement>) => {
    if (move.isMutating) {
      e.preventDefault();
      return;
    }
    dragSlotRef.current = slot;
    e.dataTransfer.effectAllowed = "move";
    e.dataTransfer.setData("text/plain", String(slot));
  };

  const handleDragOver = (slot: number) => (e: DragEvent<HTMLLIElement>) => {
    if (dragSlotRef.current === null) return;
    e.preventDefault();
    setDropTargetSlot(slot);
  };

  const handleDrop = (slot: number) => (e: DragEvent<HTMLLIElement>) => {
    e.preventDefault();
    const from = dragSlotRef.current;
    dragSlotRef.current = null;
    setDropTargetSlot(null);
    if (from === null) return;
    runMove(from, slot);
  };

  const handleDragEnd = (): void => {
    dragSlotRef.current = null;
    setDropTargetSlot(null);
  };

  const handleGripKeyDown =
    (slot: number) => (e: KeyboardEvent<HTMLButtonElement>) => {
      if (e.key === "ArrowUp") {
        e.preventDefault();
        runMove(slot, slot - 1);
      } else if (e.key === "ArrowDown") {
        e.preventDefault();
        runMove(slot, slot + 1);
      }
    };

  const unpinAction = useConfirmedAction({
    action: async () => {
      if (pendingDelete === null) return;
      await deleteTrendTopic(pendingDelete.id);
    },
    successMessage: m.range_kitecontent_trends_delete_success(),
    onDone: () => {
      setPendingDelete(null);
      onChanged();
    },
  });

  const unpin = (topic: TrendTopic): void => {
    if (isUnpinning) return;
    setIsUnpinning(true);
    deleteTrendTopic(topic.id)
      .then(() => {
        toast.success(m.range_kitecontent_trends_unpin_success());
        onChanged();
      })
      .catch((err: unknown) => {
        toast.danger(toErrorMessage(err, m.range_network_unknown_error()));
      })
      .finally(() => {
        setIsUnpinning(false);
      });
  };

  return (
    <section
      aria-label={m.range_kitecontent_trends_list_title()}
      className="flex flex-col gap-cog-2 rounded-lg border border-cog-border bg-cog-surface p-cog-4"
    >
      <header className="flex items-start justify-between gap-cog-3">
