/**
 * TrendsTab — the real Trends tab of the X content admin page (Epic #262
 * trends slice; replaces TrendsTabPlaceholder).
 *
 * The tab itself is now just the shared {@link useTrends} reader wired to
 * ONE combined card, {@link TrendsListCard}: loading renders a status line;
 * a cold-load error (no last-good data yet) renders the server
 * error.message with a Retry that refetches; once data has loaded, the tab
 * hands the lists straight to the card and gets `onChanged`/`refreshing`
 * back for it to call into `refetch`.
 *
 * There used to be a separate custom-topics card, an auto-trends card, and a
 * read-only "participant order" preview stitched together below them,
 * because a custom topic's `position` was a slot in a MERGED order that
 * lived in neither card — so the preview existed to show what that merge
 * actually produced. `TrendsListCard` renders that merge directly as the
 * one editable list, so the preview (and the intro line explaining the
 * two-block contract) has nothing left to explain and is gone.
 *
 * cog-* tokens — ADMIN surface (the participant card in KiteApp is the x-*
 * twin of this data).
 */

import { type ReactElement } from "react";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { useTrends } from "../../hooks/useTrends";
import { KiteContentErrorRetry } from "./KiteContentErrorRetry";
import { TrendsListCard } from "./TrendsListCard";

export interface TrendsTabProps {
  readonly exerciseId: string;
}

export function TrendsTab({ exerciseId }: TrendsTabProps): ReactElement {
  const trends = useTrends(exerciseId);

  if (trends.state === "loading") {
    return (
      <p
        role="status"
        className="py-cog-6 text-center text-body-sm text-cog-text-tertiary"
      >
        {m.range_kitecontent_trends_loading()}
      </p>
    );
  }

  if (trends.state === "error") {
    return (
      <KiteContentErrorRetry message={trends.message} onRetry={trends.refetch} />
    );
  }

  return (
    <div className="flex max-w-2xl flex-col gap-cog-4">
      {trends.staleError !== null && (
        <p role="alert" className="text-body-sm text-cog-text-secondary">
          {trends.staleError}
        </p>
      )}
      <TrendsListCard
        exerciseId={exerciseId}
        topics={trends.custom}
        autoTrends={trends.auto}
        refreshing={trends.refreshing}
        onChanged={trends.refetch}
      />
    </div>
  );
}


