/**
 * WhatsHappeningCard — the Timeline tab's trends side card (X content admin,
 * Epic #262 trends slice). Sits to the RIGHT of the post list at lg+ widths
 * (stacked below on smaller), surfacing the top 4 trends off the same
 * {@link useTrends} reader as the Trends tab, in the same merged order the
 * Trends tab's participant-order preview shows: custom topics sit at their
 * own slots among the auto trends (see {@link mergeTrends}), so the order an
 * instructor sets here is the order participants get.
 *
 * QUIET by design: renders nothing while loading, on error (the trends fetch
 * must never block the timeline), or when both lists are empty. cog-* tokens —
 * ADMIN surface (the x-* twin lives in KiteApp's right rail).
 */

import { type ReactElement } from "react";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { useTrends } from "../../hooks/useTrends";
import { mergeTrends } from "./mergeTrends";

const TOP_ENTRIES = 4;

export interface WhatsHappeningCardProps {
  readonly exerciseId: string;
}

export function WhatsHappeningCard({
  exerciseId,
}: WhatsHappeningCardProps): ReactElement | null {
  const trends = useTrends(exerciseId);
  if (trends.state !== "data" || trends.staleError !== null) return null;

  const entries = mergeTrends(trends.custom, trends.auto).slice(0, TOP_ENTRIES);
  if (entries.length === 0) return null;

  return (
    <aside
      aria-label={m.range_kitecontent_whats_happening_title()}
      className="w-full lg:w-cog-29 lg:shrink-0"
    >
      <section className="flex flex-col gap-cog-2 rounded-lg border border-cog-border bg-cog-surface p-cog-4">
        <h2 className="text-heading-md text-cog-text-primary">
          {m.range_kitecontent_whats_happening_title()}
        </h2>
        <ol className="flex flex-col">
          {entries.map((entry) =>
            entry.kind === "custom" ? (
              <li
                key={`custom-${entry.topic.id}`}
                className="flex items-center justify-between gap-cog-2 border-b border-cog-divider py-cog-2 last:border-b-0"
              >
                <span className="truncate text-body-sm font-semibold text-cog-text-primary">
                  {entry.topic.label}
                </span>
                <span className="inline-flex shrink-0 items-center gap-cog-1 rounded-pill bg-cog-surface-muted px-cog-2 py-cog-0-5 text-micro font-medium text-cog-text-secondary">
                  {m.range_kitecontent_trends_pinned_badge()}
                  {entry.postCount !== null && (
                    <>
                      <span aria-hidden="true">·</span>
                      <span>
                        {m.range_kitecontent_trends_post_count({
                          count: entry.postCount,
                        })}
                      </span>
                    </>
                  )}
                </span>
              </li>
            ) : (
              <li
                key={`auto-${entry.trend.label}`}
                className="flex flex-col border-b border-cog-divider py-cog-2 last:border-b-0"
              >
                <span className="truncate text-body-sm font-semibold text-cog-text-primary">
                  {entry.trend.label}
                </span>
                <span className="truncate text-caption text-cog-text-tertiary">
                  {m.range_kitecontent_trends_post_count({
                    count: entry.trend.post_count,
                  })}
                </span>
              </li>
            ),
          )}
        </ol>
      </section>
    </aside>
  );
}


